<?php
require __DIR__.'/../includes/bootstrap.php';require_login();$uid=(int)current_user()['id'];
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=post_string('action');$item=(int)($_POST['item_id']??0);
if($action==='remove'){$st=$conn->prepare("DELETE ci FROM cart_items ci JOIN cart c ON c.id=ci.cart_id WHERE ci.id=? AND c.user_id=?");$st->bind_param('ii',$item,$uid);$st->execute();}
if($action==='update'){$qty=max(1,min(10,(int)($_POST['quantity']??1)));$st=$conn->prepare("UPDATE cart_items ci JOIN cart c ON c.id=ci.cart_id SET ci.quantity=? WHERE ci.id=? AND c.user_id=?");$st->bind_param('iii',$qty,$item,$uid);$st->execute();}
redirect('cart/index.php');}
$st=$conn->prepare("SELECT ci.id item_id,ci.quantity,b.id book_id,b.title,b.author,b.price,b.stock FROM cart c JOIN cart_items ci ON ci.cart_id=c.id JOIN books b ON b.id=ci.book_id WHERE c.user_id=?");$st->bind_param('i',$uid);$st->execute();$items=$st->get_result()->fetch_all(MYSQLI_ASSOC);$total=array_sum(array_map(fn($x)=>(float)$x['price']*(int)$x['quantity'],$items));
$pageTitle='Your bag';require __DIR__.'/../includes/header.php';?>
<section class="page-hero"><div class="container"><p class="eyebrow">YOUR READING LIST</p><h1>Your <em>bag.</em></h1></div></section><section class="container section"><?php if(!$items):?><div class="empty-state"><h2>Your bag is waiting for a story.</h2><a class="btn btn-dark" href="<?=e(url('books/index.php'))?>">Browse books</a></div><?php else:?><div class="cart-layout"><div><?php foreach($items as $it):?><div class="cart-row"><div class="mini-cover">P</div><div class="cart-details"><h3><?=e($it['title'])?></h3><p><?=e($it['author'])?> · <?=money($it['price'])?></p><form method="post" class="inline-form"><?=csrf_field()?><input type="hidden" name="item_id" value="<?=$it['item_id']?>"><input type="hidden" name="action" value="update"><input type="number" name="quantity" value="<?=$it['quantity']?>" min="1" max="10"><button class="text-link">Update</button></form></div><strong><?=money($it['price']*$it['quantity'])?></strong><form method="post"><?=csrf_field()?><input type="hidden" name="item_id" value="<?=$it['item_id']?>"><input type="hidden" name="action" value="remove"><button class="remove-btn" aria-label="Remove">×</button></form></div><?php endforeach;?></div><aside class="summary"><h2>Order summary</h2><p><span>Subtotal</span><strong><?=money($total)?></strong></p><p><span>Shipping</span><span>Calculated at checkout</span></p><hr><p class="summary-total"><span>Total</span><strong><?=money($total)?></strong></p><a class="btn btn-dark full" href="<?=e(url('cart/checkout.php'))?>">Continue to checkout ↗</a></aside></div><?php endif;?></section>
<?php require __DIR__.'/../includes/footer.php';?>
